// ---------------------------------------------------------------------------
// 9. Cross-Context Replay
// ---------------------------------------------------------------------------

#[test]
fn interop_cross_context_replay_fails() {
    let v = load_vectors();
    let ed = Ed25519Provider;
    let ml = MlDsa65Provider;
    let av = &v["attack_vectors"]["cross_context_replay"];
    let comp_sig = parse_composite_sig(&av["composite_sig"]);
    let payload_key = av["payload_key"].as_str().unwrap();
    let verify_ctx = av["verify_context"].as_str().unwrap();
    let sign_ctx = av["sign_context"].as_str().unwrap();
    let canonical = v["canonicalization"][payload_key]["expected_canonical"].as_str().unwrap();
    let ed_pk = v["test_keys"]["ed25519"]["public_key_b64"].as_str().unwrap();
    let ml_pk = v["test_keys"]["ml_dsa_65"]["public_key_b64"].as_str().unwrap();

    let wrong = composite_verify(
        &ed, Some(&ml as &dyn CryptoProvider), verify_ctx, canonical.as_bytes(),
        &comp_sig, ed_pk, Some(ml_pk),
    ).unwrap();
    assert!(!wrong.valid, "cross-context replay should fail");

    let correct = composite_verify(
        &ed, Some(&ml as &dyn CryptoProvider), sign_ctx, canonical.as_bytes(),
        &comp_sig, ed_pk, Some(ml_pk),
    ).unwrap();
    assert!(correct.valid, "correct context should pass");
}

// ---------------------------------------------------------------------------
// 10. Session Splicing
// ---------------------------------------------------------------------------

#[test]
fn interop_session_splicing() {
    let v = load_vectors();
    let ed = Ed25519Provider;
    let ml = MlDsa65Provider;
    let ed_pk = v["test_keys"]["ed25519"]["public_key_b64"].as_str().unwrap();
    let ml_pk = v["test_keys"]["ml_dsa_65"]["public_key_b64"].as_str().unwrap();
    let sa = &v["session_splicing"]["session_a"];
    let sb = &v["session_splicing"]["session_b"];

    let nonce_a = sa["nonce"].as_str().unwrap();
    let nonce_b = sb["nonce"].as_str().unwrap();
    assert_ne!(nonce_a, nonce_b, "session nonces must differ");

    let passport_nonce = sa["passport"]["session_nonce"].as_str().unwrap();
    let intent_nonce = sb["intent"]["session_nonce"].as_str().unwrap();
    assert_ne!(passport_nonce, intent_nonce, "cross-session nonces must mismatch");

    // Passport A verifies
    let passport_canonical = sa["passport_canonical"].as_str().unwrap();
    let passport_sig = parse_composite_sig(&sa["passport_composite_sig"]);
    let pa = composite_verify(
        &ed, Some(&ml as &dyn CryptoProvider), CTX_AGENT_PASSPORT,
        passport_canonical.as_bytes(), &passport_sig, ed_pk, Some(ml_pk),
    ).unwrap();
    assert!(pa.valid, "passport A should verify");

    // Intent B verifies
    let intent_canonical = sb["intent_canonical"].as_str().unwrap();
    let intent_sig = parse_composite_sig(&sb["intent_composite_sig"]);
    let ib = composite_verify(
        &ed, Some(&ml as &dyn CryptoProvider), CTX_INTENT,
        intent_canonical.as_bytes(), &intent_sig, ed_pk, Some(ml_pk),
    ).unwrap();
    assert!(ib.valid, "intent B should verify");
}

#[test]
fn canonicalization_edge_cases() {
    use dcp_ai::v2::canonicalize::canonicalize_v2;
    let v = load_vectors();
    let edge = v["canonicalization"]["edge_cases"]["vectors"]
        .as_array()
        .expect("edge_cases.vectors array missing");
    for vec in edge {
        let name = vec["name"].as_str().unwrap_or("?");
        // Pull the input either from the literal `input` field or by
        // re-parsing `input_json` (used for source-literal cases the
        // vectors file cannot represent directly).
        let payload: Value = if let Some(raw_json) = vec["input_json"].as_str() {
            serde_json::from_str(raw_json)
                .unwrap_or_else(|e| panic!("{name}: bad input_json: {e}"))
        } else if !vec["input"].is_null() {
            vec["input"].clone()
        } else if let Some(_) = vec.get("input") {
            // Explicit JSON null is a valid input.
            vec["input"].clone()
        } else {
            panic!("{name}: neither input nor input_json")
        };

        let expects_error = vec["expects_error"].as_bool().unwrap_or(false);
        let result = canonicalize_v2(&payload);
        if expects_error {
            assert!(
                result.is_err(),
                "{name}: expected error, got {:?}",
                result
            );
        } else {
            let want = vec["canonical"].as_str().expect("canonical field");
            let got = result.unwrap_or_else(|e| panic!("{name}: {e}"));
            assert_eq!(got, want, "{name}: canonical mismatch");
        }
    }
}

// ---------------------------------------------------------------------------
// Signed bundle verification (bundle_vectors.json)
// ---------------------------------------------------------------------------

/// Under every verification mode, the shared signed bundle must verify, each
/// must_reject case's mutations (VERIFICATION.md V2-7 / V2-8) and each
/// must_reject_bundles entry must be rejected with an error naming
/// error_contains, and the classical-only routine control must get its
/// expected verdict.
#[test]
fn signed_bundle_vectors() {
    let data = fs::read_to_string(vectors_path().with_file_name("bundle_vectors.json"))
        .expect("read bundle vectors");
    let vectors: Value = serde_json::from_str(&data).expect("parse bundle vectors");
    let signed = &vectors["signed_bundle"];
    let assert_rejected = |result: &V2VerificationResult, case: &Value, mode: &str| {
        let want = case["error_contains"].as_str().expect("error_contains");
        assert!(!result.verified, "{mode}: {} must be rejected", case["name"]);
        assert!(
            result.errors.iter().any(|e| e.to_lowercase().contains(want)),
            "{mode}: {}: no error mentions {want}: {:?}",
            case["name"],
            result.errors
        );
    };
    // A case's verifier_policy_overrides replace those fields of the mode's policy.
    let policy_for = |policy: &VerifierPolicy, case: &Value| -> VerifierPolicy {
        let mut merged = serde_json::to_value(policy).expect("policy");
        if let Some(overrides) = case.get("verifier_policy_overrides") {
            for (field, value) in overrides.as_object().expect("verifier_policy_overrides") {
                merged[field] = value.clone();
            }
        }
        serde_json::from_value(merged).expect("case policy")
    };

    for mode in ["classical_only", "hybrid_preferred", "hybrid_required", "pq_only"] {
        let policy = VerifierPolicy {
            default_mode: mode.into(),
            risk_overrides: ["low", "medium", "high"].iter().map(|t| (t.to_string(), mode.to_string())).collect(),
            ..VerifierPolicy::default()
        };
        let result = verify_signed_bundle_v2_with_policy(signed, &policy);
        assert!(result.verified, "{mode}: signed_bundle must verify: {:?}", result.errors);

        for case in vectors["must_reject"].as_array().expect("must_reject") {
            let mut mutated = signed.clone();
            for mutation in case["mutations"].as_array().expect("mutations") {
                let mut node = &mut mutated;
                for key in mutation["path"].as_array().expect("path") {
                    node = &mut node[key.as_str().expect("path key")];
                }
                *node = mutation["value"].clone();
            }
            assert_rejected(&verify_signed_bundle_v2_with_policy(&mutated, &policy), case, mode);
        }
        for case in vectors["must_accept_bundles"].as_array().expect("must_accept_bundles") {
            let result = verify_signed_bundle_v2_with_policy(&case["signed_bundle"], &policy_for(&policy, case));
            assert!(result.verified, "{mode}: {} must verify: {:?}", case["name"], result.errors);
        }
        for case in vectors["must_reject_bundles"].as_array().expect("must_reject_bundles") {
            let result = verify_signed_bundle_v2_with_policy(&case["signed_bundle"], &policy_for(&policy, case));
            assert_rejected(&result, case, mode);
        }
        let control = &vectors["classical_only_routine_bundle"];
        let result = verify_signed_bundle_v2_with_policy(&control["signed_bundle"], &policy);
        assert_eq!(result.verified, control["verified_by_mode"][mode], "{mode}: control: {:?}", result.errors);
    }

    // The default policy maps the low-risk passport to classical_only; the
    // result reports the tier and the mode the tier raised it to.
    let control = verify_signed_bundle_v2(&vectors["classical_only_routine_bundle"]["signed_bundle"]);
    assert!(control.verified, "control: {:?}", control.errors);
    assert_eq!((control.resolved_tier.as_str(), control.verification_mode.as_str()), ("routine", "classical_only"));
    let payment = verify_signed_bundle_v2(&vectors["must_reject_bundles"][0]["signed_bundle"]);
    assert!(!payment.verified, "{} must be rejected", vectors["must_reject_bundles"][0]["name"]);
    assert_eq!((payment.resolved_tier.as_str(), payment.verification_mode.as_str()), ("elevated", "hybrid_required"));

    let unknown = VerifierPolicy { default_mode: "strict".into(), risk_overrides: Default::default(), ..VerifierPolicy::default() };
    assert!(!verify_signed_bundle_v2_with_policy(signed, &unknown).verified, "an unknown policy mode must fail closed");
    // Only default_mode and risk_overrides are enforced, so another setting
    // must not pass silently.
    let tuned = VerifierPolicy { accepted_classical_algs: vec!["ed448".into()], ..VerifierPolicy::default() };
    assert!(!verify_signed_bundle_v2_with_policy(signed, &tuned).verified, "a policy field the verifier does not enforce must fail closed");
}

/// A bundle whose checkpoints, audit entries, artifacts, keys, session times,
/// nonces or signature block have the wrong JSON type is rejected with errors,
/// never a panic (V2-4, V2-12, V2-13, V2-14).
#[test]
fn hostile_shapes_are_rejected() {
    let data = fs::read_to_string(vectors_path().with_file_name("bundle_vectors.json"))
        .expect("read bundle vectors");
    let vectors: Value = serde_json::from_str(&data).expect("parse bundle vectors");
    let base = vectors["must_accept_bundles"]
        .as_array()
        .expect("must_accept_bundles")
        .iter()
        .find(|c| c["name"] == "pq_checkpoint_over_the_trail")
        .expect("pq_checkpoint_over_the_trail");
    let pointers = [
        "/bundle/pq_checkpoints",
        "/bundle/pq_checkpoints/0",
        "/bundle/pq_checkpoints/0/checkpoint_id",
        "/bundle/pq_checkpoints/0/event_range",
        "/bundle/pq_checkpoints/0/event_range/count",
        "/bundle/pq_checkpoints/0/composite_sig",
        "/bundle/manifest/pq_checkpoints",
        "/bundle/audit_entries",
        "/bundle/audit_entries/0",
        "/bundle/audit_entries/0/intent_hash",
        "/bundle/agent_passport/payload/status",
        "/bundle/agent_passport/payload/keys",
        "/bundle/agent_passport/payload/keys/0/public_key_b64",
        "/bundle/responsible_principal_record/payload/expires_at",
        "/bundle/responsible_principal_record/payload/binding_keys",
        "/bundle/intent/payload",
        "/bundle/manifest/session_issued_at",
        "/bundle/manifest/session_expires_at",
        "/bundle/audit_entries/0/policy_decision",
        "/bundle/policy_decision/payload/decision",
        "/signature/signer",
        "/signature/signer/id",
        "/signature/signer/kids",
        "/signature/signer/kids/1",
        "/signature/composite_sig/pq",
        "/signature/manifest_hash",
        "/signature/hash_alg",
        "/bundle/policy_decision/payload/session_nonce",
        "/bundle/audit_entries/1/session_nonce",
        "/bundle/pq_checkpoints/0/session_nonce",
        "/bundle/agent_passport/payload/keys/1/public_key_b64",
    ];
    let values = [
        Value::Null,
        serde_json::json!(-1),
        serde_json::json!("x"),
        serde_json::json!([null]),
        serde_json::json!({}),
    ];
    // A maximum the unchanged bundle is within, so the session window is checked.
    let policy = VerifierPolicy {
        max_session_duration_seconds: Some(3_000_000_000),
        ..VerifierPolicy::default()
    };
    let result = verify_signed_bundle_v2_with_policy(&base["signed_bundle"], &policy);
    assert!(result.verified, "{:?}", result.errors);
    for pointer in pointers {
        for value in &values {
            let mut signed = base["signed_bundle"].clone();
            let node = signed
                .pointer_mut(pointer)
                .unwrap_or_else(|| panic!("{pointer}"));
            if node == value {
                continue; // the bundle already holds it, as the RPR's null expires_at
            }
            *node = value.clone();
            let result = verify_signed_bundle_v2_with_policy(&signed, &policy);
            assert!(
                !result.verified && !result.errors.is_empty(),
                "{pointer} = {value}"
            );
        }
    }
}

/// The TypeScript DEFAULT_VERIFIER_POLICY, Phase 3 fields included, decodes as a
/// VerifierPolicy equal to the Rust default, and its advisory_rejected_algs is
/// enforced, as are require_session_expiry and require_audience_binding.
#[test]
fn default_verifier_policy_vector() {
    let data = fs::read_to_string(vectors_path().with_file_name("bundle_vectors.json"))
        .expect("read bundle vectors");
    let vectors: Value = serde_json::from_str(&data).expect("parse bundle vectors");
    let policy: VerifierPolicy =
        serde_json::from_value(vectors["default_verifier_policy"].clone()).expect("TS default policy");
    assert_eq!(policy, VerifierPolicy::default());
    let result = verify_signed_bundle_v2_with_policy(&vectors["signed_bundle"], &policy);
    assert!(result.verified, "{:?}", result.errors);

    let mut advisory = vectors["default_verifier_policy"].clone();
    advisory["advisory_rejected_algs"] = serde_json::json!(["ml-dsa-65"]);
    let advisory: VerifierPolicy = serde_json::from_value(advisory).expect("advisory policy");
    let result = verify_signed_bundle_v2_with_policy(&vectors["signed_bundle"], &advisory);
    assert!(!result.verified, "an advisory-rejected algorithm must fail verification");
    assert!(result.errors.iter().any(|e| e.contains("rejected by active advisory")), "{:?}", result.errors);

    // The session and audience fields of verifier_policy.schema.json decode and
    // are enforced: the shared bundle expires, but names no intended verifier.
    let mut fields = vectors["default_verifier_policy"].clone();
    fields["require_session_expiry"] = serde_json::json!(true);
    fields["verifier_id"] = serde_json::json!("verifier:interop");
    let expiry: VerifierPolicy = serde_json::from_value(fields.clone()).expect("session and audience fields");
    assert_eq!(
        (expiry.require_session_expiry, expiry.require_audience_binding, expiry.verifier_id.as_deref()),
        (true, false, Some("verifier:interop"))
    );
    let result = verify_signed_bundle_v2_with_policy(&vectors["signed_bundle"], &expiry);
    assert!(result.verified, "{:?}", result.errors);
    fields["require_audience_binding"] = serde_json::json!(true);
    let audience: VerifierPolicy = serde_json::from_value(fields).expect("audience binding");
    let result = verify_signed_bundle_v2_with_policy(&vectors["signed_bundle"], &audience);
    assert_eq!(result.errors, ["Policy requires audience binding but manifest does not include intended_verifier"]);
}

/// wasm_verify_signed_bundle_v2 takes the TypeScript DEFAULT_VERIFIER_POLICY as is.
#[cfg(feature = "wasm")]
#[test]
fn wasm_verify_accepts_the_typescript_default_policy() {
    use dcp_ai::wasm::wasm_verify_signed_bundle_v2;

    let data = fs::read_to_string(vectors_path().with_file_name("bundle_vectors.json"))
        .expect("read bundle vectors");
    let vectors: Value = serde_json::from_str(&data).expect("parse bundle vectors");
    let policy = Some(vectors["default_verifier_policy"].to_string());
    let result: Value =
        serde_json::from_str(&wasm_verify_signed_bundle_v2(&vectors["signed_bundle"].to_string(), policy)).unwrap();
    assert_eq!(result["verified"], true, "{}", result["errors"]);

    // With the schema's session and audience fields too.
    let mut fields = vectors["default_verifier_policy"].clone();
    fields["require_session_expiry"] = serde_json::json!(true);
    fields["require_audience_binding"] = serde_json::json!(true);
    fields["verifier_id"] = serde_json::json!("verifier:interop");
    let result: Value = serde_json::from_str(&wasm_verify_signed_bundle_v2(
        &vectors["signed_bundle"].to_string(),
        Some(fields.to_string()),
    ))
    .unwrap();
    assert_eq!(result["verified"], false);
    assert_eq!(result["errors"][0], "Policy requires audience binding but manifest does not include intended_verifier");
}

/// wasm_sign_payload, wasm_build_bundle and wasm_sign_bundle produce a bundle
/// that wasm_verify_signed_bundle_v2 accepts.
#[cfg(feature = "wasm")]
#[test]
fn wasm_build_sign_verify_round_trip() {
    use dcp_ai::wasm::*;
    use serde_json::json;

    let principal: Value = serde_json::from_str(&wasm_generate_hybrid_keypair()).unwrap();
    let agent: Value = serde_json::from_str(&wasm_generate_hybrid_keypair()).unwrap();
    let entries = |k: &Value| {
        json!([
            {"kid": k["classical"]["kid"], "alg": "ed25519", "public_key_b64": k["classical"]["public_key_b64"], "status": "active"},
            {"kid": k["pq"]["kid"], "alg": "ml-dsa-65", "public_key_b64": k["pq"]["public_key_b64"], "status": "active"},
        ])
    };
    let s = |k: &Value, slot: &str, field: &str| k[slot][field].as_str().unwrap().to_string();
    let sign = |context: &str, payload: Value, k: &Value| {
        wasm_sign_payload(
            context,
            &payload.to_string(),
            &s(k, "classical", "secret_key_b64"),
            &s(k, "classical", "kid"),
            &s(k, "pq", "secret_key_b64"),
            &s(k, "pq", "kid"),
        )
    };

    let nonce = "ab".repeat(32);
    let intent = sign(
        CTX_INTENT,
        json!({"intent_id": "i-1", "session_nonce": nonce, "agent_id": "a-1", "human_id": "h-1"}),
        &agent,
    );
    let intent_hash = serde_json::from_str::<Value>(&intent).unwrap()["payload_hash"].clone();
    // Audit entries name the intent, by id and payload hash, the agent and the
    // principal, and record the policy decision (V2-14).
    let entry = |audit_id: &str, prev_hash: String| {
        json!({
            "audit_id": audit_id, "session_nonce": nonce, "prev_hash": prev_hash,
            "intent_id": "i-1", "intent_hash": intent_hash, "agent_id": "a-1", "human_id": "h-1",
            "policy_decision": "approved",
        })
    };
    let audit1 = entry("audit-1", "GENESIS".into());
    let audit1_hash = sha256_hex(canonicalize_v2(&audit1).unwrap().as_bytes());
    let audit2 = entry("audit-2", format!("sha256:{}", audit1_hash));

    let passport = json!({
        "agent_id": "a-1", "session_nonce": nonce, "keys": entries(&agent),
        "principal_binding_reference": "h-1", "status": "active",
    });
    let decision = sign(
        CTX_POLICY_DECISION,
        json!({"intent_id": "i-1", "session_nonce": nonce, "risk_score": 200, "decision": "approve"}),
        &agent,
    );
    let bundle = wasm_build_bundle(
        &sign(CTX_RESPONSIBLE_PRINCIPAL, json!({"human_id": "h-1", "session_nonce": nonce, "binding_keys": entries(&principal)}), &principal),
        &sign(CTX_AGENT_PASSPORT, passport, &agent),
        &intent,
        &decision,
        &json!([audit1, audit2]).to_string(),
        &nonce,
    );
    let signed = wasm_sign_bundle(
        &bundle,
        &s(&principal, "classical", "secret_key_b64"),
        &s(&principal, "classical", "kid"),
        &s(&principal, "pq", "secret_key_b64"),
        &s(&principal, "pq", "kid"),
    );
    let result: Value = serde_json::from_str(&wasm_verify_signed_bundle_v2(&signed, None)).unwrap();
    assert_eq!(result["verified"], true, "{}", result["errors"]);
    // An intent without the schema fields is elevated, so the default policy's
    // hybrid_preferred is raised to hybrid_required.
    assert_eq!(result["verification_mode"], "hybrid_required");

    // A policy must be a complete VerifierPolicy: a partial one fails closed.
    let partial = Some(r#"{"default_mode":"classical_only"}"#.to_string());
    let result: Value = serde_json::from_str(&wasm_verify_signed_bundle_v2(&signed, partial)).unwrap();
    assert_eq!(result["verified"], false);
    assert!(result["errors"][0].as_str().unwrap().contains("Policy parse error"), "{}", result["errors"]);
}

/// A verifier policy applies to V2 bundles, so with one a V1 bundle is
/// rejected instead of being verified without it.
#[cfg(feature = "wasm")]
#[test]
fn wasm_verify_rejects_v1_bundles_under_a_policy() {
    use dcp_ai::wasm::wasm_verify_signed_bundle_v2;

    let tests_dir = vectors_path().parent().unwrap().parent().unwrap().parent().unwrap().to_path_buf();
    let v1 = fs::read_to_string(tests_dir.join("conformance/examples/citizenship_bundle.signed.json")).unwrap();
    let policy = serde_json::to_string(&VerifierPolicy::default()).unwrap();
    let result: Value = serde_json::from_str(&wasm_verify_signed_bundle_v2(&v1, Some(policy))).unwrap();
    assert_eq!(result["verified"], false);
    assert!(result["errors"][0].as_str().unwrap().contains("V1"), "{}", result["errors"]);
}

/// RFC 3339 timestamps: each input parses to its instant in Unix milliseconds,
/// or is rejected.
#[test]
fn rfc3339_vectors() {
    let vectors = load_vectors();
    let cases = vectors["rfc3339"]["cases"].as_array().expect("rfc3339 cases");
    assert!(!cases.is_empty());
    for case in cases {
        let got = case["input"].as_str().and_then(parse_rfc3339_millis);
        assert_eq!(got, case["epoch_ms"].as_i64(), "{}", case["input"]);
    }
}

// ---------------------------------------------------------------------------
// Security tier (spec §14.2)
// ---------------------------------------------------------------------------

fn security_tier_cases() -> Vec<Value> {
    let cases = load_vectors()["security_tier"]["cases"].as_array().cloned().unwrap_or_default();
    assert!(!cases.is_empty(), "no security_tier vectors found");
    cases
}

#[test]
fn security_tier_vectors() {
    for case in security_tier_cases() {
        let tier = compute_security_tier(&case["intent"], case.get("policy_decision"));
        let got = serde_json::json!({
            "tier": tier.as_str(),
            "verification_mode": tier_to_verification_mode(tier),
            "checkpoint_interval": tier_to_checkpoint_interval(tier),
        });
        assert_eq!(got, case["expected"], "{}", case["name"]);
    }
}

#[cfg(feature = "wasm")]
#[test]
fn security_tier_vectors_wasm_binding() {
    for case in security_tier_cases() {
        let policy_decision = case.get("policy_decision").map(Value::to_string);
        let out = dcp_ai::wasm::wasm_compute_security_tier(&case["intent"].to_string(), policy_decision);
        let got: Value = serde_json::from_str(&out).unwrap();
        assert_eq!(got, case["expected"], "{}", case["name"]);
    }
}

#[test]
fn effective_mode_vectors() {
    let vectors = load_vectors();
    let cases = vectors["security_tier"]["effective_mode"]["cases"].as_array().expect("effective_mode cases");
    assert!(!cases.is_empty());
    for case in cases {
        // SecurityTier is a closed enum: an unknown name cannot reach this API.
        let tier = match case["tier"].as_str().unwrap() {
            "routine" => SecurityTier::Routine,
            "standard" => SecurityTier::Standard,
            "elevated" => SecurityTier::Elevated,
            "maximum" => SecurityTier::Maximum,
            _ => continue,
        };
        let policy_mode = case["policy_mode"].as_str().unwrap();
        assert_eq!(
            effective_verification_mode(policy_mode, tier),
            case["expected"].as_str().unwrap(),
            "{} + {}",
            policy_mode,
            case["tier"]
        );
    }
}
